CREATE TYPE public.user_role AS ENUM ('analyst','kam','ops_manager','admin');
CREATE TYPE public.occ_channel AS ENUM ('portal','email','phone','whatsapp','account_meeting','site_visit');
CREATE TYPE public.occ_type AS ENUM ('complaint','incident','request');
CREATE TYPE public.occ_level AS ENUM ('high','medium','low');
CREATE TYPE public.occ_severity AS ENUM ('S1','S2','S3','S4');
CREATE TYPE public.occ_status AS ENUM ('registered','in_analysis','in_treatment','awaiting_customer','solution_proposed','reopened','closed_resolved','closed_no_evaluation','closed_unfounded');
CREATE TYPE public.event_kind AS ENUM ('customer_update','customer_question','internal_note','status_change','customer_reply','solution','evaluation','system');
CREATE TYPE public.event_visibility AS ENUM ('customer','internal','system');
CREATE TYPE public.cause_kind AS ENUM ('root','contributing');
CREATE TYPE public.cause_status AS ENUM ('hypothesis','validating','confirmed','discarded');
CREATE TYPE public.cause_6m AS ENUM ('method','machine','manpower','material','measurement','environment');
CREATE TYPE public.action_type AS ENUM ('containment','correction','corrective','preventive');
CREATE TYPE public.action_status AS ENUM ('open','in_progress','done','cancelled');
CREATE TYPE public.problem_status AS ENUM ('open','analysis','action_plan','effectiveness_check','closed','cancelled');
CREATE TYPE public.eval_resolved AS ENUM ('yes','partial','no');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL, active boolean NOT NULL DEFAULT true);
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.user_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.current_app_role() RETURNS public.user_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT r.role FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=auth.uid() AND p.active $$;
REVOKE ALL ON FUNCTION public.current_app_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.current_app_role() TO authenticated,service_role;
CREATE FUNCTION public.is_config_admin() RETURNS boolean LANGUAGE sql STABLE SET search_path = public AS $$ SELECT coalesce(public.current_app_role()='admin',false) $$;
REVOKE ALL ON FUNCTION public.is_config_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_config_admin() TO authenticated,service_role;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.current_app_role() IN ('ops_manager','admin'));
CREATE POLICY profile_self_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
REVOKE UPDATE ON public.profiles FROM authenticated; GRANT UPDATE(full_name) ON public.profiles TO authenticated;
CREATE POLICY role_self_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.initialize_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'full_name',''),split_part(NEW.email,'@',1),'Usuário')); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.initialize_profile() FROM PUBLIC;
CREATE TRIGGER atlas_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_profile();
CREATE TABLE public.business_calendars(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,timezone text NOT NULL DEFAULT 'America/Sao_Paulo',work_start time NOT NULL DEFAULT '08:00',work_end time NOT NULL DEFAULT '18:00',work_days smallint[] NOT NULL DEFAULT '{1,2,3,4,5}',CHECK(work_end>work_start),CHECK(cardinality(work_days)>0 AND work_days <@ ARRAY[1,2,3,4,5,6,7]::smallint[]));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.business_calendars TO authenticated; GRANT ALL ON public.business_calendars TO service_role;
ALTER TABLE public.business_calendars ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.holidays(calendar_id uuid REFERENCES public.business_calendars ON DELETE CASCADE,day date NOT NULL,description text,PRIMARY KEY(calendar_id,day));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.holidays TO authenticated; GRANT ALL ON public.holidays TO service_role;
ALTER TABLE public.holidays ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sla_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sla_policies TO authenticated; GRANT ALL ON public.sla_policies TO service_role;
ALTER TABLE public.sla_policies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sla_targets(policy_id uuid REFERENCES public.sla_policies ON DELETE CASCADE,severity public.occ_severity NOT NULL,first_response_minutes int NOT NULL CHECK(first_response_minutes>0),resolution_minutes int NOT NULL CHECK(resolution_minutes>0),update_interval_minutes int NOT NULL CHECK(update_interval_minutes>0),PRIMARY KEY(policy_id,severity));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sla_targets TO authenticated; GRANT ALL ON public.sla_targets TO service_role;
ALTER TABLE public.sla_targets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,kam_id uuid REFERENCES public.profiles,calendar_id uuid NOT NULL REFERENCES public.business_calendars,sla_policy_id uuid NOT NULL REFERENCES public.sla_policies,active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.accounts TO authenticated; GRANT ALL ON public.accounts TO service_role;
ALTER TABLE public.accounts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_members(account_id uuid REFERENCES public.accounts ON DELETE CASCADE,user_id uuid REFERENCES public.profiles ON DELETE CASCADE,PRIMARY KEY(account_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.account_members TO authenticated; GRANT ALL ON public.account_members TO service_role;
ALTER TABLE public.account_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_account_access(p_account_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id WHERE p.id=auth.uid() AND p.active AND (r.role IN ('ops_manager','admin') OR EXISTS(SELECT 1 FROM public.account_members m WHERE m.user_id=p.id AND m.account_id=p_account_id))) $$;
REVOKE ALL ON FUNCTION public.has_account_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_account_access(uuid) TO authenticated,service_role;
CREATE POLICY accounts_read ON public.accounts FOR SELECT TO authenticated USING(public.has_account_access(id));
CREATE POLICY accounts_admin ON public.accounts FOR ALL TO authenticated USING(public.is_config_admin()) WITH CHECK(public.is_config_admin());
CREATE POLICY members_read ON public.account_members FOR SELECT TO authenticated USING(public.has_account_access(account_id));
CREATE POLICY members_admin ON public.account_members FOR ALL TO authenticated USING(public.is_config_admin()) WITH CHECK(public.is_config_admin());
CREATE TABLE public.account_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES public.accounts,name text NOT NULL,email text NOT NULL,job_title text,active boolean NOT NULL DEFAULT true,UNIQUE(id,account_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.account_contacts TO authenticated; GRANT ALL ON public.account_contacts TO service_role;
ALTER TABLE public.account_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.account_contacts FOR SELECT TO authenticated USING(public.has_account_access(account_id));
CREATE POLICY contacts_admin ON public.account_contacts FOR ALL TO authenticated USING(public.is_config_admin()) WITH CHECK(public.is_config_admin());
CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,parent_id uuid REFERENCES public.categories,active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['business_calendars','holidays','sla_policies','sla_targets','categories'] LOOP EXECUTE format('CREATE POLICY config_read ON public.%I FOR SELECT TO authenticated USING (public.current_app_role() IS NOT NULL)',t); EXECUTE format('CREATE POLICY config_admin ON public.%I FOR ALL TO authenticated USING (public.is_config_admin()) WITH CHECK (public.is_config_admin())',t); END LOOP; END $$;
CREATE TABLE public.problems(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,title text NOT NULL,account_id uuid REFERENCES public.accounts,category_id uuid REFERENCES public.categories,status public.problem_status NOT NULL DEFAULT 'open',owner_id uuid REFERENCES public.profiles,effectiveness_criteria text,effectiveness_due_date date,effectiveness_effective boolean,created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.problems TO authenticated; GRANT ALL ON public.problems TO service_role;
ALTER TABLE public.problems ENABLE ROW LEVEL SECURITY;
CREATE POLICY problems_read ON public.problems FOR SELECT TO authenticated USING ((account_id IS NOT NULL AND public.has_account_access(account_id)) OR (account_id IS NULL AND public.current_app_role() IN ('ops_manager','admin')));
CREATE POLICY problems_write ON public.problems FOR ALL TO authenticated USING (public.current_app_role() IN ('kam','ops_manager') AND ((account_id IS NOT NULL AND public.has_account_access(account_id)) OR (account_id IS NULL AND public.current_app_role()='ops_manager'))) WITH CHECK(public.current_app_role() IN ('kam','ops_manager') AND ((account_id IS NOT NULL AND public.has_account_access(account_id)) OR (account_id IS NULL AND public.current_app_role()='ops_manager')));
CREATE TABLE public.protocol_counters(year int PRIMARY KEY,last_number bigint NOT NULL DEFAULT 0);
GRANT ALL ON public.protocol_counters TO service_role; ALTER TABLE public.protocol_counters ENABLE ROW LEVEL SECURITY;
CREATE SEQUENCE public.problem_code_sequence;
CREATE FUNCTION public.generate_problem_code() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN NEW.code := 'PRB-'||lpad(nextval('public.problem_code_sequence')::text,4,'0'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.generate_problem_code() FROM PUBLIC;
CREATE TRIGGER problem_code BEFORE INSERT ON public.problems FOR EACH ROW EXECUTE FUNCTION public.generate_problem_code();
CREATE TABLE public.occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),protocol text UNIQUE NOT NULL,account_id uuid NOT NULL REFERENCES public.accounts,contact_id uuid NOT NULL,channel public.occ_channel NOT NULL,type public.occ_type NOT NULL,category_id uuid NOT NULL REFERENCES public.categories,subcategory_id uuid REFERENCES public.categories,subject text NOT NULL CHECK(char_length(subject) BETWEEN 5 AND 140),description text NOT NULL CHECK(length(trim(description))>0),references_text text,financial_impact numeric(14,2) CHECK(financial_impact>=0),customer_expectation text NOT NULL CHECK(length(trim(customer_expectation))>0),occurred_at timestamptz,impact public.occ_level NOT NULL,urgency public.occ_level NOT NULL,severity public.occ_severity NOT NULL,status public.occ_status NOT NULL DEFAULT 'registered',assignee_id uuid REFERENCES public.profiles,created_by uuid NOT NULL REFERENCES public.profiles,problem_id uuid REFERENCES public.problems,solution_text text,unfounded_justification text,created_at timestamptz NOT NULL DEFAULT now(),first_response_at timestamptz,first_response_due_at timestamptz NOT NULL,resolution_started_at timestamptz NOT NULL,resolution_due_at timestamptz NOT NULL,paused_since timestamptz,paused_business_minutes int NOT NULL DEFAULT 0,next_update_due_at timestamptz,solution_proposed_at timestamptz,closed_at timestamptz,reopen_count int NOT NULL DEFAULT 0,first_response_breached boolean NOT NULL DEFAULT false,resolution_breached boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(contact_id,account_id) REFERENCES public.account_contacts(id,account_id));
GRANT SELECT,INSERT ON public.occurrences TO authenticated; GRANT ALL ON public.occurrences TO service_role;
ALTER TABLE public.occurrences ENABLE ROW LEVEL SECURITY;
CREATE INDEX occurrences_account_status ON public.occurrences(account_id,status); CREATE INDEX occurrences_status_due ON public.occurrences(status,resolution_due_at); CREATE INDEX occurrences_category_created ON public.occurrences(category_id,created_at);
CREATE POLICY occurrences_read ON public.occurrences FOR SELECT TO authenticated USING(public.has_account_access(account_id));
CREATE POLICY occurrences_insert ON public.occurrences FOR INSERT TO authenticated WITH CHECK(public.has_account_access(account_id) AND created_by=auth.uid() AND status='registered');
CREATE FUNCTION public.calculate_severity(p_impact public.occ_level,p_urgency public.occ_level) RETURNS public.occ_severity LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN p_impact='high' AND p_urgency='high' THEN 'S1' WHEN (p_impact='high' AND p_urgency='medium') OR (p_impact='medium' AND p_urgency='high') THEN 'S2' WHEN (p_impact='high' AND p_urgency='low') OR (p_impact='medium' AND p_urgency='medium') OR (p_impact='low' AND p_urgency='high') THEN 'S3' ELSE 'S4' END::public.occ_severity $$;
REVOKE ALL ON FUNCTION public.calculate_severity(public.occ_level,public.occ_level) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.calculate_severity(public.occ_level,public.occ_level) TO authenticated,service_role;
CREATE FUNCTION public.occurrence_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE y int; n bigint; BEGIN IF TG_OP='INSERT' THEN y:=extract(year FROM NEW.created_at AT TIME ZONE 'America/Sao_Paulo'); INSERT INTO public.protocol_counters(year,last_number) VALUES(y,1) ON CONFLICT(year) DO UPDATE SET last_number=public.protocol_counters.last_number+1 RETURNING last_number INTO n; NEW.protocol:='OC-'||y::text||'-'||lpad(n::text,greatest(4,length(n::text)),'0'); END IF; NEW.severity:=public.calculate_severity(NEW.impact,NEW.urgency); IF NEW.occurred_at>now() THEN RAISE EXCEPTION 'A data da ocorrência não pode ser futura'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.occurrence_identity() FROM PUBLIC;
CREATE TRIGGER occurrence_identity BEFORE INSERT OR UPDATE OF impact,urgency,occurred_at ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.occurrence_identity();
CREATE TABLE public.occurrence_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES public.occurrences ON DELETE RESTRICT,kind public.event_kind NOT NULL,visibility public.event_visibility NOT NULL,author_id uuid REFERENCES public.profiles,body text,from_status public.occ_status,to_status public.occ_status,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.occurrence_events TO authenticated; GRANT SELECT,INSERT ON public.occurrence_events TO service_role;
ALTER TABLE public.occurrence_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX events_occurrence_created ON public.occurrence_events(occurrence_id,created_at DESC);
CREATE FUNCTION public.has_occurrence_access(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.occurrences o WHERE o.id=p_id AND public.has_account_access(o.account_id)) $$;
REVOKE ALL ON FUNCTION public.has_occurrence_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_occurrence_access(uuid) TO authenticated,service_role;
CREATE POLICY events_read ON public.occurrence_events FOR SELECT TO authenticated USING(public.has_occurrence_access(occurrence_id));
CREATE POLICY events_insert ON public.occurrence_events FOR INSERT TO authenticated WITH CHECK(public.has_occurrence_access(occurrence_id) AND author_id=auth.uid() AND kind='internal_note' AND visibility='internal' AND from_status IS NULL AND to_status IS NULL AND public.current_app_role() IN ('analyst','kam','ops_manager'));
CREATE FUNCTION public.reject_event_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'O histórico não pode ser editado ou apagado'; END $$;
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON public.occurrence_events FOR EACH ROW EXECUTE FUNCTION public.reject_event_mutation();
CREATE TABLE public.causes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid REFERENCES public.occurrences,problem_id uuid REFERENCES public.problems,code text NOT NULL,kind public.cause_kind NOT NULL,status public.cause_status NOT NULL DEFAULT 'hypothesis',category public.cause_6m,description text NOT NULL,evidence text,whys text[] NOT NULL DEFAULT '{}',created_by uuid REFERENCES public.profiles,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(occurrence_id,problem_id)>=1),CHECK(cardinality(whys)<=7));
GRANT SELECT,INSERT,UPDATE ON public.causes TO authenticated; GRANT ALL ON public.causes TO service_role;
ALTER TABLE public.causes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid REFERENCES public.occurrences,problem_id uuid REFERENCES public.problems,cause_id uuid REFERENCES public.causes,type public.action_type NOT NULL,what text NOT NULL,why text,where_text text,how text,how_much numeric(14,2),owner_id uuid NOT NULL REFERENCES public.profiles,due_date date NOT NULL,status public.action_status NOT NULL DEFAULT 'open',done_at timestamptz,evidence_note text,gates_solution boolean GENERATED ALWAYS AS (type IN ('containment','correction')) STORED,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(occurrence_id,problem_id)>=1),CHECK(type IN ('containment','correction') OR cause_id IS NOT NULL));
GRANT SELECT,INSERT,UPDATE ON public.actions TO authenticated; GRANT ALL ON public.actions TO service_role;
ALTER TABLE public.actions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_problem_access(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.problems p WHERE p.id=p_id AND ((p.account_id IS NOT NULL AND public.has_account_access(p.account_id)) OR (p.account_id IS NULL AND public.current_app_role() IN ('ops_manager','admin')))) $$;
REVOKE ALL ON FUNCTION public.has_problem_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_problem_access(uuid) TO authenticated,service_role;
CREATE FUNCTION public.has_work_access(p_occ uuid,p_problem uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (p_occ IS NULL OR public.has_occurrence_access(p_occ)) AND (p_problem IS NULL OR public.has_problem_access(p_problem)) AND (p_occ IS NOT NULL OR p_problem IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.has_work_access(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_work_access(uuid,uuid) TO authenticated,service_role;
CREATE FUNCTION public.can_manage_work(p_occ uuid,p_problem uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_work_access(p_occ,p_problem) AND (public.current_app_role() IN ('kam','ops_manager') OR (public.current_app_role()='analyst' AND p_occ IS NOT NULL AND EXISTS(SELECT 1 FROM public.occurrences o WHERE o.id=p_occ AND o.assignee_id=auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.can_manage_work(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage_work(uuid,uuid) TO authenticated,service_role;
CREATE POLICY causes_read ON public.causes FOR SELECT TO authenticated USING(public.has_work_access(occurrence_id,problem_id));
CREATE POLICY causes_insert ON public.causes FOR INSERT TO authenticated WITH CHECK(public.can_manage_work(occurrence_id,problem_id) AND created_by=auth.uid());
CREATE POLICY causes_update ON public.causes FOR UPDATE TO authenticated USING(public.can_manage_work(occurrence_id,problem_id)) WITH CHECK(public.can_manage_work(occurrence_id,problem_id));
CREATE POLICY actions_read ON public.actions FOR SELECT TO authenticated USING(public.has_work_access(occurrence_id,problem_id));
CREATE POLICY actions_insert ON public.actions FOR INSERT TO authenticated WITH CHECK(public.can_manage_work(occurrence_id,problem_id));
CREATE POLICY actions_update ON public.actions FOR UPDATE TO authenticated USING(public.has_work_access(occurrence_id,problem_id) AND (public.can_manage_work(occurrence_id,problem_id) OR (owner_id=auth.uid() AND public.current_app_role()='analyst'))) WITH CHECK(public.has_work_access(occurrence_id,problem_id) AND (public.can_manage_work(occurrence_id,problem_id) OR (owner_id=auth.uid() AND public.current_app_role()='analyst')));
CREATE TABLE public.attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid REFERENCES public.occurrences,action_id uuid REFERENCES public.actions,storage_path text NOT NULL,filename text NOT NULL,mime_type text,size_bytes int CHECK(size_bytes BETWEEN 0 AND 15728640),visibility public.event_visibility NOT NULL DEFAULT 'internal',uploaded_by uuid REFERENCES public.profiles,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(occurrence_id,action_id)>=1));
GRANT SELECT,INSERT ON public.attachments TO authenticated; GRANT ALL ON public.attachments TO service_role;
ALTER TABLE public.attachments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_attachment_parent_access(p_occ uuid,p_action uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (p_occ IS NULL OR public.has_occurrence_access(p_occ)) AND (p_action IS NULL OR EXISTS(SELECT 1 FROM public.actions a WHERE a.id=p_action AND public.has_work_access(a.occurrence_id,a.problem_id))) AND (p_occ IS NOT NULL OR p_action IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.has_attachment_parent_access(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_attachment_parent_access(uuid,uuid) TO authenticated,service_role;
CREATE POLICY attachments_read ON public.attachments FOR SELECT TO authenticated USING(public.has_attachment_parent_access(occurrence_id,action_id));
CREATE POLICY attachments_insert ON public.attachments FOR INSERT TO authenticated WITH CHECK(public.has_attachment_parent_access(occurrence_id,action_id) AND uploaded_by=auth.uid());
CREATE TABLE public.evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES public.occurrences,cycle int NOT NULL DEFAULT 1,token_hash text UNIQUE NOT NULL CHECK(token_hash ~ '^[0-9a-f]{64}$'),token_expires_at timestamptz NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),reminders_sent int NOT NULL DEFAULT 0,answered_at timestamptz,resolved public.eval_resolved,csat smallint CHECK(csat BETWEEN 1 AND 5),ces smallint CHECK(ces BETWEEN 1 AND 7),missing_text text,comment text CHECK(length(comment)<=1000),UNIQUE(occurrence_id,cycle));
GRANT SELECT( id,occurrence_id,cycle,sent_at,reminders_sent,answered_at,resolved,csat,ces,missing_text,comment) ON public.evaluations TO authenticated; GRANT ALL ON public.evaluations TO service_role;
ALTER TABLE public.evaluations ENABLE ROW LEVEL SECURITY;
CREATE POLICY evaluations_read ON public.evaluations FOR SELECT TO authenticated USING(public.has_occurrence_access(occurrence_id));
CREATE TABLE public.sla_alerts(occurrence_id uuid REFERENCES public.occurrences ON DELETE CASCADE,alert_key text NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(occurrence_id,alert_key));
GRANT SELECT ON public.sla_alerts TO authenticated; GRANT ALL ON public.sla_alerts TO service_role;
ALTER TABLE public.sla_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY alerts_read ON public.sla_alerts FOR SELECT TO authenticated USING(public.has_occurrence_access(occurrence_id));
COMMENT ON TABLE public.user_roles IS 'Protected app roles are separate from editable profile fields; no automatic privileged role assignment.';
COMMENT ON TABLE public.occurrences IS 'Stage 2 foundation: SLA deadline calculation and transition RPCs are added in stage 3. No direct authenticated UPDATE grant.';
COMMENT ON TABLE public.evaluations IS 'Tokens and writes restricted to server-only evaluation handlers; internal users receive only safe evaluation columns.';